INSERT OR IGNORE INTO projects (id, slug, title, status, color_class, digest, summary, created_at, updated_at, published_at) VALUES ('legacy-una-ventana-para-el-arte', 'una-ventana-para-el-arte', 'Una ventana para el arte', 'published', 'bg-dora-pink', 'Sistema editorial para el Museo de Artes Visuales MAVI UC, que promueve una experiencia museográfica reflexiva e interactiva.', 'Impulsado por el Departamento de Educación e Inclusión del MAVI UC, este proyecto buscó transformar la experiencia de los visitantes mediante folletos que promovieran una interacción reflexiva con las obras.

Ante el desafío de producir un material atractivo, adaptable y eficiente, se implementó un sistema gráfico que preservaba la identidad visual del museo, pero con suficiente flexibilidad para adaptarse a la estética particular de cada exposición. Esta solución optimizó los procesos de diseño y distribución, consolidándose como un formato replicable que se materializó con tres exposiciones que utilizaron este modelo; sentando las bases para futuras ediciones.', 1787784320335, 1787784320335, 1787784320335);
INSERT OR IGNORE INTO project_tags (project_id, tag_key) VALUES ('legacy-una-ventana-para-el-arte', 'editorial');
