INSERT OR IGNORE INTO projects (id, slug, title, status, color_class, digest, summary, created_at, updated_at, published_at) VALUES ('legacy-kombucha-loyca', 'kombucha-loyca', 'Kombucha Loyca', 'published', 'bg-dora-orange', 'Rebranding para reposicionar una bebida artesanal en el mercado gastronómico contemporáneo.', 'Loyca impulsó un rebranding con el objetivo de aumentar su alcance en el mercado, reposicionando su kombucha más allá del nicho orgánico convencional, para consolidarse como una alternativa versátil y gourmet en el mercado gastronómico; orientándose a restaurantes, coctelería de autor y cafés de especialidad. 

El nuevo enfoque de identidad mantiene la esencia artesanal de Loyca, combinándola con un carácter contemporáneo, fresco y experimental. Este replanteamiento fortaleció la identidad de la marca, facilitando también su integración en nuevos contextos de consumo, aumentando su percepción de calidad, autenticidad y adaptabilidad.', 1787784320335, 1787784320335, 1787784320335);
INSERT OR IGNORE INTO project_tags (project_id, tag_key) VALUES ('legacy-kombucha-loyca', 'branding');
