INSERT OR IGNORE INTO projects (id, slug, title, status, color_class, digest, summary, created_at, updated_at, published_at) VALUES ('legacy-frankenstein', 'frankenstein', 'Frankenstein', 'published', 'bg-dora-sky', 'Afiche cultural desarrollado como proyecto universitario para conmemorar los 200 años de Frankenstein.', 'Proyecto universitario de difusión cultural, desarrollado para conmemorar los más de 200 años de la publicación de Frankenstein (1818) y acercar su legado a nuevas generaciones.  El afiche se centra en reinterpretar una de las principales tensiones de la obra: la contraposición entre la bondad del monstruo y la maldad del ser humano.
Bajo este concepto, la propuesta invita a una lectura contemporánea de la obra, abordando los dilemas éticos y existenciales que plantea. La propuesta utiliza recursos visuales metafóricos para enriquecer la interpretación y promover una conexión crítica y emocional con el espectador contemporáneo.', 1787784320335, 1787784320335, 1787784320335);
INSERT OR IGNORE INTO project_tags (project_id, tag_key) VALUES ('legacy-frankenstein', 'graphic');
