INSERT OR IGNORE INTO projects (id, slug, title, status, color_class, digest, summary, created_at, updated_at, published_at) VALUES ('legacy-chao-reunionitis', 'chao-reunionitis', 'Chao Reunionitis', 'published', 'bg-dora-green', 'Campaña gráfica interna para Teck, orientada a promover una gestión eficiente de las reuniones de trabajo.', 'Frente a la problemática del exceso de reuniones y su impacto en la productividad y el bienestar de los equipos, un equipo de liderazgo interno de Teck impulsó una campaña de sensibilización orientada a promover una gestión más eficiente del tiempo durante las reuniones de trabajo.

La campaña tomó como eje conceptual la "reunionitis", un término humorístico que permitió abordar el tema de forma cercana y amena, facilitando la identificación y reflexión de los colaboradores. A partir de este concepto se desarrollaron piezas gráficas ilustradas que, mediante el humor, transmitieron buenas prácticas para planificar y asistir a reuniones de manera más efectiva. La estrategia se complementó con acciones de difusión interna que reforzaron el mensaje en distintos espacios de trabajo, favoreciendo la adopción de comportamientos más eficientes.      ', 1787784320335, 1787784320335, 1787784320335);
INSERT OR IGNORE INTO project_tags (project_id, tag_key) VALUES ('legacy-chao-reunionitis', 'graphic');
