INSERT OR IGNORE INTO projects (id, slug, title, status, color_class, digest, summary, created_at, updated_at, published_at) VALUES ('legacy-a-solas-el-jardin', 'a-solas-el-jardin', 'A solas, el jardín', 'draft', 'bg-dora-violet', 'Publicación editorial ilustrada que aborda la soledad emocional en jóvenes a través de una metáfora visual y relatos personales.', 'Proyecto de título enfocado en la problemática de la soledad emocional en personas jóvenes, desarrollado a través de una publicación editorial ilustrada. El proyecto utiliza representaciones metafóricas de experiencias cotidianas para abrir espacios de interpretación e identificación personal, acompañadas de relatos anónimos que invitan a la reflexión y al ejercicio introspectivo.

La propuesta busca generar una experiencia de lectura sensible y auténtica, combinando una atmósfera visual introspectiva con el carácter crudo de las vivencias narradas. El desarrollo del proyecto implicó un extenso proceso de investigación, entrevistas personales, iteración de contenidos y validaciones cualitativas, con el objetivo de construir un dispositivo editorial capaz de dialogar de manera genuina con las emociones del lector.', 1787784320335, 1787784320335, NULL);
INSERT OR IGNORE INTO project_tags (project_id, tag_key) VALUES ('legacy-a-solas-el-jardin', 'editorial');
INSERT OR IGNORE INTO project_tags (project_id, tag_key) VALUES ('legacy-a-solas-el-jardin', 'illustration');
