INSERT OR IGNORE INTO projects (id, slug, title, status, color_class, digest, summary, created_at, updated_at, published_at) VALUES ('legacy-hicigrafia', 'hicigrafia', 'Hicigrafía', 'published', 'bg-dora-yellow', 'Proyecto de ilustración y arte gráfico que nace de una forma particular de mirar el mundo.', 'Hicigrafía es un proyecto de ilustración autoral que nace de la búsqueda por encontrar una forma propia de mirar el mundo. Su nombre surge de la firma “hicidora”, seudónimo construido a partir de Isidora, y se transforma en hicigrafía como una manera de nombrar este universo de imágenes.

      Las ilustraciones toman situaciones, objetos y personajes reconocibles para transformarlos en escenas absurdas, humorísticas o simbólicas, donde algo aparentemente simple puede esconder una segunda lectura. A través de la caricatura y las asociaciones inesperadas, el proyecto explora temas y experiencias más complejas desde lugares cercanos, buscando provocar una sonrisa, una reflexión o ese momento en que algo hace sentido de una manera inesperada.
      ', 1787784320335, 1787784320335, 1787784320335);
